//! The reviewed fixtures (`fixtures/split/i3/`, generated by the independent
//! `admission_cases.py`) are the expectation for the I3 contract; these tests
//! only compare against them.
use super::*;
use serde::de::DeserializeOwned;
use serde_json::Value;

const ADMISSION: &str = include_str!("../../../../fixtures/split/i3/admission_cases.json");
const LAUNCH: &str = include_str!("../../../../fixtures/split/i3/launch_exchange.json");
const HEADERS: &str = include_str!("../../../../fixtures/split/i3/headers.json");
const ENVELOPES: &str = include_str!("../../../../fixtures/split/i3/envelopes.json");
const OPERATIONS: &str = include_str!("../../../../fixtures/split/i3/admin_operations.json");

fn json(text: &str) -> Value {
    serde_json::from_str(text).expect("fixture is JSON")
}

fn cases<'a>(fixture: &'a Value, key: &str) -> &'a [Value] {
    let cases = fixture[key].as_array().expect("fixture case list");
    assert!(!cases.is_empty(), "{key}: zero selected cases is a failure");
    cases
}

fn decode<T: DeserializeOwned>(value: &Value, name: &Value) -> T {
    serde_json::from_value(value.clone()).unwrap_or_else(|error| panic!("{name}: {error}"))
}

fn strings(value: &Value) -> Vec<String> {
    decode(value, &Value::Null)
}

fn serialized<T: Serialize>(value: T) -> Value {
    serde_json::to_value(value).unwrap()
}

fn run_admission(case: &Value) {
    let name = &case["name"];
    let request: RequestFacts = decode(&case["request"], name);
    let session: Option<SessionFacts> = decode(&case["session"], name);
    let expected: Admission = decode(&case["expect"], name);
    assert_eq!(admit(&request, session.as_ref()), expected, "{name}");
    if let Admission::Refuse { status, code } = expected {
        assert_eq!(code.status(), status, "{name}");
    }
}

#[test]
fn admission_cases_match_the_reviewed_rules() {
    let fixture = json(ADMISSION);
    assert_eq!(fixture["schema"], "airk.split-fixture.i3-admission/1");
    for case in cases(&fixture, "cases") {
        run_admission(case);
    }
}

#[test]
fn h1_peer_cases_refuse_every_unproven_peer() {
    let fixture = json(LAUNCH);
    for case in cases(&fixture, "admission") {
        run_admission(case);
    }
}

#[test]
fn every_session_failure_gets_one_uniform_refusal() {
    let fixture = json(ADMISSION);
    let uniform: Vec<&Value> = cases(&fixture, "cases")
        .iter()
        .filter(|case| {
            case["expect"]["status"] == 401 && case["expect"]["code"] != "admin_bearer_refused"
        })
        .map(|case| &case["expect"])
        .collect();
    assert!(uniform.len() >= 10, "selected {} cases", uniform.len());
    assert!(uniform.iter().all(|expect| *expect == uniform[0]));
}

