#[test]
fn cookies_are_counted_by_exact_name_and_refused_on_the_bearer_plane() {
    let fixture = json(ADMISSION);
    for case in cases(&fixture, "cookies") {
        let headers = strings(&case["headers"]);
        assert_eq!(
            admin_cookies(&headers).len() as u64,
            case["admin_cookies"].as_u64().unwrap(),
            "{headers:?}"
        );
    }
    for case in cases(&fixture, "bearer_plane") {
        let headers = strings(&case["headers"]);
        let expected = match bearer_plane_cookie(&headers) {
            Some(code) => serde_json::json!({"status": code.status(), "code": code}),
            None => Value::Null,
        };
        assert_eq!(expected, case["expect"], "{headers:?}");
    }
}

