#[test]
fn launch_codes_are_exchanged_once_without_an_oracle() {
    let fixture = json(LAUNCH);
    let url = &fixture["launch_url"];
    let port = u16::try_from(url["port"].as_u64().unwrap()).unwrap();
    assert_eq!(launch_url(port, url["code"].as_str().unwrap()), url["url"]);
    for case in cases(&fixture, "exchanges") {
        let name = &case["name"];
        let stored: Option<LaunchCodeFacts> = decode(&case["stored"], name);
        let now = case["now_ms"].as_u64().unwrap();
        let outcome = decode_exchange(case["body"].as_str().unwrap().as_bytes())
            .and_then(|request| exchange(&request, stored.as_ref(), now));
        let observed = match outcome {
            Ok(()) => serde_json::json!({"outcome": "accepted"}),
            Err(code) => {
                serde_json::json!({"outcome": "refused", "status": code.status(), "code": code})
            }
        };
        assert_eq!(observed, case["expect"], "{name}");
    }
}

#[test]
fn exchange_responses_decode_and_validate_as_reviewed() {
    let fixture = json(LAUNCH);
    for case in cases(&fixture, "responses") {
        let response: ExchangeResponse = decode(&case["json"], &case["name"]);
        assert_eq!(serialized(&response), case["json"], "{}", case["name"]);
        response.validate().unwrap();
        assert!(!format!("{response:?}").contains(&response.csrf));
    }
    for case in cases(&fixture, "invalid_responses") {
        assert!(
            serde_json::from_value::<ExchangeResponse>(case["json"].clone()).is_err(),
            "{}",
            case["name"]
        );
    }
    for case in cases(&fixture, "rejected_responses") {
        let response: ExchangeResponse = decode(&case["json"], &case["name"]);
        assert_eq!(
            response.validate(),
            Err(case["reason"].as_str().unwrap()),
            "{}",
            case["name"]
        );
    }
    let code = fixture["launch_url"]["code"].as_str().unwrap();
    let request = ExchangeRequest {
        code: code.to_owned(),
    };
    assert!(!format!("{request:?}").contains(code));
}

#[test]
fn response_headers_match_the_reviewed_sets() {
    let fixture = json(HEADERS);
    let kinds = fixture["kinds"].as_object().unwrap();
    assert_eq!(kinds.len(), 5);
    for (kind, expected) in kinds {
        let parsed: ResponseKind = decode(&Value::String(kind.clone()), &Value::Null);
        let mut observed: Vec<Vec<String>> = response_headers(parsed)
            .into_iter()
            .map(|(name, value)| vec![name.to_owned(), value.to_owned()])
            .collect();
        let mut expected: Vec<Vec<String>> = decode(expected, &Value::Null);
        observed.sort();
        expected.sort();
        assert_eq!(observed, expected, "{kind}");
        for prefix in strings(&fixture["never_sent_prefixes"]) {
            assert!(observed.iter().all(|pair| !pair[0].starts_with(&prefix)));
        }
    }
    assert_eq!(fixture["cookie_name"], COOKIE_NAME);
    assert_eq!(fixture["csrf_header"], CSRF_HEADER);
    let cookie = &fixture["set_cookie"];
    assert_eq!(
        session_cookie(cookie["value"].as_str().unwrap()),
        cookie["header"]
    );
    assert_eq!(fixture["clear_cookie"], CLEAR_SESSION_COOKIE);
    assert_eq!(
        strings(&fixture["redacted_request_headers"]),
        REDACTED_REQUEST_HEADERS
    );
    assert_eq!(
        strings(&fixture["exchange_secret_fields"]),
        EXCHANGE_SECRET_FIELDS
    );
    assert_eq!(
        fixture["bare_status_exceptions"],
        serialized(BARE_STATUS_EXCEPTIONS)
    );
}

#[test]
fn error_codes_and_classes_match_the_catalog() {
    let fixture = json(ENVELOPES);
    assert_eq!(fixture["envelope_schema"], ENVELOPE_SCHEMA);
    let classes = fixture["status_by_class"].as_object().unwrap();
    assert_eq!(classes.len(), ErrorClass::ALL.len());
    for class in ErrorClass::ALL {
        let name = serialized(class);
        assert_eq!(classes[name.as_str().unwrap()], class.status(), "{name}");
    }
    let rows = cases(&fixture, "codes");
    assert_eq!(rows.len(), AdminCode::ALL.len());
    for (row, code) in rows.iter().zip(AdminCode::ALL) {
        assert_eq!(row["code"], serialized(code));
        assert_eq!(AdminCode::parse(row["code"].as_str().unwrap()), Some(code));
        assert_eq!(row["class"], serialized(code.class()), "{}", row["code"]);
        assert_eq!(row["status"], code.status(), "{}", row["code"]);
        assert_eq!(row["retryable"], code.retryable(), "{}", row["code"]);
        FailureEnvelope::new(code).validate().unwrap();
    }
}

fn validate(envelope: &Envelope) -> Result<(), &'static str> {
    match envelope {
        Envelope::Success(success) => success.validate(),
        Envelope::Failure(failure) => failure.validate(),
    }
}

#[test]
fn envelopes_round_trip_and_refuse_as_reviewed() {
    let fixture = json(ENVELOPES);
    for case in cases(&fixture, "valid") {
        let envelope: Envelope = decode(&case["json"], &case["name"]);
        assert_eq!(serialized(&envelope), case["json"], "{}", case["name"]);
        validate(&envelope).unwrap_or_else(|reason| panic!("{}: {reason}", case["name"]));
    }
    for case in cases(&fixture, "invalid") {
        assert!(
            serde_json::from_value::<Envelope>(case["json"].clone()).is_err(),
            "{}",
            case["name"]
        );
    }
    for case in cases(&fixture, "rejected_after_decoding") {
        let envelope: Envelope = decode(&case["json"], &case["name"]);
        assert_eq!(
            validate(&envelope),
            Err(case["reason"].as_str().unwrap()),
            "{}",
            case["name"]
        );
    }
    for case in cases(&fixture, "stream_lines") {
        let line: StreamLine = decode(&case["json"], &case["name"]);
        assert_eq!(serialized(&line), case["json"], "{}", case["name"]);
    }
    for case in cases(&fixture, "invalid_stream_lines") {
        assert!(
            serde_json::from_value::<StreamLine>(case["json"].clone()).is_err(),
            "{}",
            case["name"]
        );
    }
}

#[test]
fn operation_table_follows_the_reviewed_rules() {
    let fixture = json(OPERATIONS);
    let enumerations = &fixture["enumerations"];
    assert_eq!(enumerations["plane"], serialized(Plane::ALL));
    assert_eq!(enumerations["surface"], serialized(Surface::ALL));
    assert_eq!(
        enumerations["authorization"],
        serialized(Authorization::ALL)
    );
    assert_eq!(enumerations["effect"], serialized(Effect::ALL));
    assert_eq!(enumerations["idempotency"], serialized(Idempotency::ALL));
    assert_eq!(enumerations["conformance"], serialized(Conformance::ALL));
    assert_eq!(enumerations["key_mode"], serialized(KeyMode::ALL));
    assert_eq!(enumerations["confirmation"], serialized(Confirmation::ALL));
    let never: Vec<NeverOverHttp> = decode(&fixture["never_over_http"], &Value::Null);
    assert!(!never.is_empty());
    let rows: Vec<OperationRow> = decode(&fixture["operations"], &Value::Null);
    assert!(!rows.is_empty());
    assert_eq!(serialized(&rows), fixture["operations"]);
    validate_table(&rows, &never).unwrap();
    assert!(
        rows.iter()
            .any(|row| row.surfaces.contains(&Surface::Admin))
    );
    for case in cases(&fixture, "invalid_tables") {
        let rows: Vec<OperationRow> = decode(&case["rows"], &case["name"]);
        assert_eq!(
            validate_table(&rows, &never),
            Err(case["reason"].as_str().unwrap()),
            "{}",
            case["name"]
        );
    }
}

/// The checked-in schema is the reviewed output; a mismatch fails and writes
/// the observation to the temporary directory (never rewrites the file unless
/// `AIRK_WRITE_CONTRACT_SCHEMA=1` is set explicitly).
#[test]
fn admin_contract_schema_matches_the_checked_in_copy() {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../packages/contracts-gen/i3.schema.json");
    let observed = serde_json::to_string_pretty(&schema_document()).unwrap() + "\n";
    if std::env::var_os("AIRK_WRITE_CONTRACT_SCHEMA").is_some_and(|value| value == "1") {
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        std::fs::write(&path, &observed).unwrap();
    }
    let expected = std::fs::read_to_string(&path)
        .unwrap_or_default()
        .replace("\r\n", "\n");
    if expected != observed {
        let note = std::env::temp_dir().join("airk-admin-i3.schema.observed.json");
        std::fs::write(&note, &observed).unwrap();
        panic!(
            "I3 schema differs from {}; observation written to {}",
            path.display(),
            note.display()
        );
    }
}
